public class StateRootCollector {
  public static void addParentStateRoots(
      final Spec spec, final BeaconState blockSlotState, final StoreTransaction transaction) {
    final UInt64 newBlockSlot = blockSlotState.getSlot();
    final UInt64 slotsPerHistoricalRoot =
        spec.atSlot(newBlockSlot).getConfig().getSlotsPerHistoricalRoot();
    final UInt64 minimumSlot =
        newBlockSlot.isGreaterThan(slotsPerHistoricalRoot)
            ? newBlockSlot.minusMinZero(slotsPerHistoricalRoot)
            : UInt64.ZERO;
    final Bytes32 parentBlockRoot = blockSlotState.getLatestBlockHeader().getParentRoot();
