        slot.isGreaterThanOrEqualTo(minimumSlot);
        slot = slot.minusMinZero(1)) {
      final Optional<Bytes32> value = getValue(spec, blockSlotState, slot, parentBlockRoot);
      if (value.isEmpty()) {
        break;
      }
      transaction.putStateRoot(value.get(), slot);
    }
  }
}"""

